28	static atb::Status AllReduceOperationCreate(const nlohmann::json &paramJson, atb::Operation **op)
29	{
30	    atb::infer::AllReduceParam param;
31	    param.rank = paramJson["rank"].get<int>();
32	    param.rankSize = paramJson["rankSize"].get<int>();
33	    if (paramJson.find("rankRoot") != paramJson.end()) {
34	        param.rankRoot = paramJson["rankRoot"].get<int>();
35	    }
36	    if (paramJson.find("backend") != paramJson.end()) {
37	        param.backend = paramJson["backend"].get<std::string>();
38	    }
39	    if (paramJson.find("allReduceType") != paramJson.end()) {
40	        param.allReduceType = paramJson["allReduceType"].get<std::string>();
41	    }
42	    if (paramJson.contains("commMode")) {
43	        param.commMode = atb::infer::CommMode(paramJson["commMode"].get<int>());
44	    }
45	    if (paramJson.find("rankTableFile") != paramJson.end()) {
46	        param.rankTableFile = paramJson["rankTableFile"].get<std::string>();
47	    }
48	    if (paramJson.find("commDomain") != paramJson.end()) {
49	        param.commDomain = paramJson["commDomain"].get<std::string>();
50	    }
51	    if (paramJson.contains("quantType")) {
52	        param.quantType = atb::infer::AllReduceParam::QuantType(paramJson["quantType"].get<int>());
53	    }
54	    if (paramJson.contains("outDataType")) {
55	        param.outDataType = aclDataType(paramJson["outDataType"].get<int32_t>());
56	    }
57	    ATB_LOG(INFO) << "AllReduceParam rank:" << param.rank << ", rankSize:" << param.rankSize
58	                  << ", rankRoot:" << param.rankRoot << ", backend:" << param.backend
59	                  << ", commDomain:" << param.commDomain << ", quantType:" << param.quantType
60	                  << ", outDataType:" << param.outDataType;
61	    if (paramJson.contains("rsv")) {
62	        for (size_t i = 0; i < paramJson["rsv"].size(); i++) {
63	            param.rsv[i] = paramJson["rsv"].at(i).get<int8_t>();
64	        }
65	    }
66	    return CreateOperation(param, op);
67	}
