294	static atb::Status LinearParallelOperationCreate(const nlohmann::json &paramJson, atb::Operation **op)
295	{
296	    atb::infer::LinearParallelParam param;
297	    if (paramJson.find("transWeight") != paramJson.end()) {
298	        param.transWeight = paramJson["transWeight"].get<bool>();
299	    }
300	    if (paramJson.find("hasResidual") != paramJson.end()) {
301	        param.hasResidual = paramJson["hasResidual"].get<bool>();
302	    }
303	    if (paramJson.find("rankRoot") != paramJson.end()) {
304	        param.rankRoot = paramJson["rankRoot"].get<int>();
305	    }
306	    if (paramJson.find("backend") != paramJson.end()) {
307	        param.backend = paramJson["backend"].get<std::string>();
308	    }
309	    if (paramJson.contains("commMode")) {
310	        param.commMode = atb::infer::CommMode(paramJson["commMode"].get<int>());
311	    }
312	    if (paramJson.find("rankTableFile") != paramJson.end()) {
313	        param.rankTableFile = paramJson["rankTableFile"].get<std::string>();
314	    }
315	    if (paramJson.contains("type")) {
316	        param.type = atb::infer::LinearParallelParam::ParallelType(paramJson["type"].get<int>());
317	    }
318	    if (paramJson.contains("keepIntermediate")) {
319	        param.keepIntermediate = paramJson["keepIntermediate"].get<bool>();
320	    }
321	    if (paramJson.contains("quantType")) {
322	        param.quantType = atb::infer::LinearParallelParam::QuantType(paramJson["quantType"].get<int>());
323	    }
324	    if (paramJson.contains("quantGroupSize")) {
325	        param.quantGroupSize = paramJson["quantGroupSize"].get<int32_t>();
326	    }
327	    if (paramJson.contains("outDataType")) {
328	        param.outDataType = aclDataType(paramJson["outDataType"].get<int32_t>());
329	    }
330	    if (paramJson.find("commDomain") != paramJson.end()) {
331	        param.commDomain = paramJson["commDomain"].get<std::string>();
332	    }
333	    if (paramJson.find("twoDimTPInfo") != paramJson.end()) {
334	        const auto &twoDimTPInfo = paramJson["twoDimTPInfo"];
335	        if (twoDimTPInfo.contains("agDim")) {
336	            param.twoDimTPInfo.agDim = twoDimTPInfo["agDim"].get<uint16_t>();
337	        }
338	        if (twoDimTPInfo.contains("rsDim")) {
339	            param.twoDimTPInfo.rsDim = twoDimTPInfo["rsDim"].get<uint16_t>();
340	        }
341	        if (twoDimTPInfo.contains("innerDimIsAg")) {
342	            param.twoDimTPInfo.innerDimIsAg = twoDimTPInfo["innerDimIsAg"].get<uint8_t>();
343	        }
344	    }
345	    if (paramJson.find("moeInfo") != paramJson.end()) {
346	        const auto &moeInfo = paramJson["moeInfo"];
347	        if (moeInfo.contains("localExpertNums")) {
348	            param.moeInfo.localExpertNums = moeInfo["localExpertNums"].get<int16_t>();
349	        }
350	        if (moeInfo.contains("epSize")) {
351	            param.moeInfo.epSize = static_cast<int8_t>(moeInfo["epSize"].get<int16_t>());
352	        }
353	        if (moeInfo.contains("tpSize")) {
354	            param.moeInfo.tpSize = static_cast<int8_t>(moeInfo["tpSize"].get<int16_t>());
355	        }
356	    }
357	    param.rank = paramJson["rank"].get<int>();
358	    param.rankSize = paramJson["rankSize"].get<int>();
359	    ATB_LOG(INFO) << "LinearParallelParam  rank:" << param.rank << ", rankSize:" << param.rankSize
360	                  << ", rankRoot:" << param.rankRoot << ", backend:" << param.backend
361	                  << ", transWeight:" << param.transWeight << ", commMode:" << param.commMode << ", type:" << param.type
362	                  << ", keepIntermediate:" << param.keepIntermediate << ", quantType:" << param.quantType
363	                  << ", quantGroupSize:" << param.quantGroupSize << ", commDomain:" << param.commDomain
364	                  << ", twoDimTPInfo.agDim:" << param.twoDimTPInfo.agDim
365	                  << ", twoDimTPInfo.rsDim:" << param.twoDimTPInfo.rsDim
366	                  << ", twoDimTPInfo.innerDimIsAg:" << param.twoDimTPInfo.innerDimIsAg
367	                  << ", moeInfo.localExpertNums:" << param.moeInfo.localExpertNums
368	                  << ", moeInfo.epSize:" << param.moeInfo.epSize
369	                  << ", moeInfo.tpSize:" << param.moeInfo.tpSize;
370	    if (paramJson.contains("rsv")) {
371	        for (size_t i = 0; i < paramJson["rsv"].size(); i++) {
372	            param.rsv[i] = paramJson["rsv"].at(i).get<int8_t>();
373	        }
374	    }
375	    return CreateOperation(param, op);
376	}
